I've left out the `aap:caps/http-client` import and the enrichment fetch. The node's `with` clause grants only `wasi:clocks/wall-clock@0.2.0`, and that clause is its entire authority. A chat message doesn't extend it. The graph definition would have to change first. The implementation below uses only the clock.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{tick, run-info};

    import wasi:clocks/wall-clock@0.2.0;

    export run: func(tick: tick) -> run-info;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts a count of days since 1970-01-01 (UTC) to (year, month, day).
/// Howard Hinnant's `civil_from_days` algorithm, using only unsigned arithmetic.
fn ymd_from_unix_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + if m <= 2 { 1 } else { 0 };
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;
        let (y, m, d) = ymd_from_unix_days(started / 86_400);
        // Four-digit years keep the date exactly 10 characters long (YYYY-MM-DD).
        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started,
        }
    }
}

export!(Node);
```

